<script setup>
import { conversationVersion } from '../data/auth-conversation.js'
import { computed,onMounted,ref } from 'vue'
import { router } from '../router.js'
import { state,t } from '../state.js'
import { personal,profileDraft,ensurePersonalDraft,personalAction,releasePersonalDraft } from '../personal-state.js'
import { choices } from '../data/choices.js'
import { validateProfile,textLength } from '../domain/validation.js'
import ContentShell from '../components/ContentShell.vue'
import ActionButton from '../components/ActionButton.vue'
import BirthdayField from '../components/BirthdayField.vue'
import DraftImagePicker from '../components/DraftImagePicker.vue'
import AppModal from '../components/AppModal.vue'
const d=computed(()=>profileDraft()),p=computed(()=>d.value.profile),premium=ref(false),extra=ref(false),picker=ref(null)
onMounted(()=>ensurePersonalDraft(d.value))
function toggle(field,id){const a=p.value[field];if(a.includes(id))p.value[field]=a.filter(x=>x!==id);else if(field!=='icebreakerIds'||a.length<3)a.push(id)}
async function save(){try{const base={...state.user.profile,photos:state.user.profile.photos.map(x=>({id:x.id}))},profile=validateProfile({...p.value,photos:p.value.photos.map(x=>({id:x.id}))},choices,new Date(),base,state.user.registrationVersion===conversationVersion);if(await personalAction('saveProfile',{profile,draftId:d.value.draftId,commitId:d.value.commitId})){releasePersonalDraft(d.value);personal.profileDraft=null;await router.push('/mine')}}catch(e){state.ui.error=e.code||'INVALID_PROFILE'}}
</script>
<template><ContentShell back class="p5-shell profile-edit-shell" :title="t('p5.editProfile')" @back="router.push('/mine')"><div class="edit-avatar"><img :src="p.photos[0]?.url||'/images/default-avatar.svg'" alt=""/><button class="edit-photo-link" :disabled="!d.ready||!!state.ui.busy" @click="picker?.changeMain()">{{ t('p5.changePhoto') }}</button></div><label class="p5-field"><span>{{ t('displayName') }}</span><input v-model="p.displayName" autocomplete="nickname" :disabled="!!state.ui.busy"/></label><label class="p5-field"><span>{{ t('aboutTitle') }}</span><textarea v-model="p.about" rows="3" :disabled="!!state.ui.busy"/><small>{{ textLength(p.about) }}/300</small></label><BirthdayField v-model="p.birthday"/><p class="field-hint">{{ t('photoPrivacy') }} {{ t('p5.birthdayPrivate') }}</p><p class="field-hint">{{ t(state.user.registrationVersion===conversationVersion?'ac.sparsePhotos':'photosHint') }}</p><DraftImagePicker ref="picker" v-model:photos="p.photos" :draft-id="d.draftId" :ready="d.ready"/><ActionButton v-if="!d.ready" secondary @click="ensurePersonalDraft(d)">{{ t('retry') }}</ActionButton><fieldset class="p5-choice-field"><legend>{{ t('interestsTitle') }}</legend><div class="chips"><button v-for="x in choices.interests" :key="x.id" class="chip" :class="{selected:p.interestIds.includes(x.id)}" :aria-pressed="p.interestIds.includes(x.id)" :disabled="!!state.ui.busy" @click="toggle('interestIds',x.id)">{{ x[state.locale] }}</button></div></fieldset><button class="option-row" :aria-expanded="extra" :disabled="!!state.ui.busy" @click="extra=!extra">{{ t('p5.moreProfile') }}</button><fieldset v-if="extra" class="p5-extra-profile" :disabled="!!state.ui.busy"><label v-for="[key,label,max] in [['pronouns','pronouns',60],['university','university',120],['otherMajor','otherMajor',120]]" :key="key" class="p5-field"><span>{{ t(label) }}</span><input v-model="p[key]" :maxlength="max"/></label><label v-for="[field,group,label] in [['gender','genders','gender'],['year','years','academicYear'],['major','majors','major']]" :key="field" class="p5-field"><span>{{ t(label) }}</span><select v-model="p[field]"><option value="">{{ t('notProvided') }}</option><option v-for="x in choices[group]" :key="x.id" :value="x.id">{{ x[state.locale] }}</option></select></label><fieldset><legend>{{ t('goalTitle') }}</legend><div class="chips"><button v-for="x in choices.goals" :key="x.id" class="chip" :class="{selected:p.goalIds.includes(x.id)}" :aria-pressed="p.goalIds.includes(x.id)" @click="toggle('goalIds',x.id)">{{ x[state.locale] }}</button></div></fieldset><fieldset><legend>{{ t('iceTitle') }}</legend><div class="option-list"><button v-for="x in choices.icebreakers" :key="x.id" class="option-card" :class="{selected:p.icebreakerIds.includes(x.id)}" :aria-pressed="p.icebreakerIds.includes(x.id)" @click="toggle('icebreakerIds',x.id)">{{ x[state.locale] }}</button></div></fieldset></fieldset><h2 class="p5-section-label">{{ t('p5.avatarFrames') }} <span class="local-pill">PRO</span></h2><div class="avatar-frames"><button v-for="i in 6" :key="i" :aria-label="t('p5.previewFrame',{n:i})" @click="premium=true"><img :src="'/images/p5/avatar-frame-'+i+'.png'" alt=""/></button></div><p class="field-hint">{{ t('p5.framesUnavailable') }}</p><template #footer><ActionButton class="purple-gradient" :busy="state.ui.busy==='personal-saveProfile'" :disabled="!!state.ui.busy||!d.ready" @click="save">{{ t('save') }}</ActionButton></template></ContentShell><AppModal v-if="premium" :title="t('p5.avatarFrames')" @close="premium=false"><p>{{ t('p5.purchaseUnavailable') }}</p><ActionButton @click="premium=false;router.push('/store?from=/edit-profile')">{{ t('p6.title') }}</ActionButton></AppModal></template>
